const nextCycleAfter = `-- name: NextCycleAfter :one
SELECT id, project_id, name, starts_on, ends_on, starts_at, ends_at, closed_at, closed_policy, created_by, created_at FROM cycles
WHERE project_id = $1
  AND id <> $2
  AND starts_at >= $3
  AND closed_at IS NULL
ORDER BY starts_at
LIMIT 1
`

type NextCycleAfterParams struct {
	ProjectID uuid.UUID
	AfterID   uuid.UUID
	EndedAt   time.Time
}

// Where unfinished work goes when a cycle ends: the first cycle starting no
// earlier than that one ended, that has not itself ended.
func (q *Queries) NextCycleAfter(ctx context.Context, arg NextCycleAfterParams) (Cycle, error) {
	row := q.db.QueryRow(ctx, nextCycleAfter, arg.ProjectID, arg.AfterID, arg.EndedAt)
	var i Cycle
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Name,
		&i.StartsOn,
		&i.EndsOn,
		&i.StartsAt,
		&i.EndsAt,
		&i.ClosedAt,
		&i.ClosedPolicy,
		&i.CreatedBy,
		&i.CreatedAt,
	)
	return i, err
}

